def get_min_hitting_set_v3(k, n):
    R = set(range(k))
    diff_sets = []
    # Arcs are {i, i+1, ..., i+k'-1} mod n
    for k_prime in range(n + 1):
        for start in range(n):
            R_prime = set((start + j) % n for j in range(k_prime))
            diff_set = R ^ R_prime
            if diff_set and diff_set != set():
                diff_sets.append(diff_set)

    # Hit all diff_sets
    for r in range(1, n + 1):
        for subset in itertools.combinations(range(n), r):
            subset_set = set(subset)
            if all(subset_set & d_set for d_set in diff_sets):
                return r
    return n

