import itertools

def count_blocks(coloring):
    n = len(coloring)
    blocks = 0
    for i in range(n):
        if coloring[i] != coloring[(i - 1) % n]:
            blocks += 1
    # Special case for all same colors
    if blocks == 0: return 1
    return blocks

def solve():
    # Try all colorings for a given n
    # A coloring is a tuple of 'B' and 'R'
    n = 4
    colorings = []
    for c in itertools.product(['B', 'R'], repeat=n):
        if count_blocks(c) <= 3:
            colorings.append(c)

    # For each coloring, find the minimum c
    min_c_for_all = 0
    for c_target in colorings:
        min_c_for_this_coloring = n
        for c_size in range(n + 1):
            found_M = False
            for M in itertools.combinations(range(n), c_size):
                # M is the set of indices Lisa hides
                M = set(M)
                # Check if c_target is the only 3-block coloring consistent with M
                consistent_colorings = []
                for c_test in colorings:
                    # Check if c_test matches c_target on M^c
                    match = True
                    for i in range(n):
                        if i not in M:
                            if c_test[i] != c_target[i]:
                                match = False
                                break
                    if match:
                        consistent_colorings.append(c_test)

                if len(consistent_colorings) == 1:
                    found_M = True
                    break
            if found_M:
                min_c_for_this_coloring = c_size
                break
        min_c_for_all = max(min_c_for_all, min_c_for_this_coloring)
        print(f"Coloring {c_target}: min c = {min_c_for_this_coloring}")

    print(f"Final min c for n={n}: {min_c_for_all}")

